// Chain two notify_fail() calls together and return the value notify_fail
// gave back.  Invalid argument types are not filtered here: the driver's
// own type check raises the exception, which is allowed to bubble up.

int chain_notify(mixed m1, mixed m2) {
    int rc = notify_fail(m1);

    notify_fail(m2);
    return rc;
}

